<script setup lang="ts">
import type { AccountType } from '~/types/finance'
const route=useRoute();const finance=useFinance();const account=computed(()=>finance.accounts.value.find(item=>item.id===route.params.id));const name=ref('');const type=ref<AccountType>('bank');const openingBalance=ref(0);const error=ref('')
watch(account,value=>{if(!value)return;name.value=value.name;type.value=value.type;openingBalance.value=value.openingBalance},{immediate:true})
async function save(){if(!account.value)return;try{await finance.updateAccount(account.value.id,{name:name.value,type:type.value,openingBalance:openingBalance.value});await navigateTo('/accounts')}catch(cause){error.value=(cause as {data?:{message?:string}})?.data?.message??'Could not update account'}}
onMounted(()=>finance.refresh().catch(()=>undefined))
</script>
<template><main class="page"><NuxtLink to="/accounts" class="text-link">← Accounts</NuxtLink><template v-if="account"><div class="eyebrow" style="margin-top:26px">Account details</div><h1 class="display">{{ account.name }}</h1><p class="muted">Current balance {{ new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB'}).format(account.balance) }}</p><form class="form" @submit.prevent="save"><div class="field"><label>Name</label><input v-model.trim="name" required></div><div class="field"><label>Type</label><select v-model="type"><option value="cash">Cash</option><option value="bank">Bank</option><option value="ewallet">e-Wallet</option><option value="other">Other</option></select></div><div class="field"><label>Opening balance</label><input v-model.number="openingBalance" type="number" step="0.01"><small class="muted">Changing this adjusts the calculated current balance.</small></div><p v-if="error" class="notice error">{{ error }}</p><button class="button accent">Save changes</button></form></template><div v-else class="empty">Account not found.</div></main></template>
